package com.mannvaasam.service;
import com.mannvaasam.model.*; import com.mannvaasam.repo.*; import org.springframework.stereotype.Service;
@Service public class DeliveryService { private final SellerProfileRepository sellers; public DeliveryService(SellerProfileRepository s){sellers=s;} public double distanceKm(double a,double b,double c,double d){double r=6371,d1=Math.toRadians(c-a),d2=Math.toRadians(d-b);double x=Math.sin(d1/2)*Math.sin(d1/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(c))*Math.sin(d2/2)*Math.sin(d2/2);return 2*r*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));} public boolean deliverable(Product p,Address a){if(a.latitude==null||a.longitude==null)return false;SellerProfile s=sellers.findByUserId(p.seller.id).orElse(null);return s!=null&&s.latitude!=null&&s.longitude!=null&&s.deliveryRadiusKm!=null&&distanceKm(s.latitude,s.longitude,a.latitude,a.longitude)<=s.deliveryRadiusKm;} }